        cfg = r.config
        n_params = cfg.get('n_params', '?')
        print(f'{r.name:45s} val/loss={vl:.4f}  params={n_params}')
        for k in sorted(cfg.keys()):
            if k not in ['splits_dir', 'wandb_group', 'wandb_name', 'agent', 'debug', 'train_samples', 'val_samples']:
                print(f'  {k}={cfg[k]}')
        print()
